<p>Our activities are carefully designed for students to build a
connection between them and their surroundings. What is unique about
these activities is that we invite locals to co-host or participate in
the events, thus giving students further opportunities to practice the
language and get a real sense of life in Germany.</p>
<br>
<p>All activities are either free or at minimal cost.</p>
<br>
<h3> <b style="color:red;"> ** Please note that starting September 2017, all our events and job announcements are posted on our <a href = https://www.facebook.com/groups/12517655820/?ref=ts&fref=ts > Facebook page </a>, as well as on the info board at the reception. **  </b> </h3>
<br>
